import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"5G 切片与 URLLC","description":"","frontmatter":{"title":"5G 切片与 URLLC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/5g-slicing.md","filePath":"cs/5g-slicing.md","lastUpdated":1789023840000}'),L={name:"cs/5g-slicing.md"};function h(_,a,E,C,A,B){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="_5g-切片与-urllc" tabindex="-1">5G 切片与 URLLC <a class="header-anchor" href="#_5g-切片与-urllc" aria-label="Permalink to &quot;5G 切片与 URLLC&quot;">​</a></h1><div class="epigraph"><p>切片把同一物理 RAN/核心切成隔离的逻辑网络；URLLC 用短时隙与高可靠编码换毫秒级空口，牺牲频谱效率。</p><footer>—— 据 3GPP TS 23.501 切片；TS 22.261 与 38 系列 URLLC 相关条款整理</footer></div><p><a href="/cs/cellular-ran-core">上一课</a> 给出 RAN 与核心。eMBB 大带宽与工厂控制不能共用同一张「尽力而为」承载。缺口是<strong>切片</strong>与 <strong>URLLC</strong>：NSI 隔离资源；URLLC 要 \\(10^{-5}\\) 量级空口可靠与毫秒延迟。本课不把卫星轨道写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DiffServ 后课给 IP hop 着色；切片更强：独立的控制面与用户面实例、SLA、可能独立的 UPF。URLLC：迷你时隙、免授权上行、重复传输，工作点远离香农极限换延迟——与 Wi‑Fi OFDMA 调度同类但有牌照与更硬的时间槽。不是 PFC：空口不能「暂停邻站一整口」来保证工厂周期。</p><p>不要把切片写成 VLAN：隔离在核心与 RAN 资源上，不止 802.1Q 标签。</p><p><span class="marginnote">eMBB / URLLC / mMTC 是 5G 三类场景。实现参差，本课钉合同：隔离与时延可靠指标，不点名某运营商套餐。</span></p><h3 id="切片强于-dscp" tabindex="-1">切片强于 DSCP <a class="header-anchor" href="#切片强于-dscp" aria-label="Permalink to &quot;切片强于 DSCP&quot;">​</a></h3><p>隔离的是实例与资源，不只 hop 着色。URLLC 用效率换尾延迟，工作点远离容量极限。实验室演示不等于全国 SLA。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：物理网 → 切片实例 → 不同 SLA。URLLC 路径：短 TTI → 编码重复 → 核心低时延转发。对照以太网 PFC：一跳反压 vs 端到端时延预算。</p>',11)),(e(),n(c,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHY%5B%22%E7%89%A9%E7%90%86%20RAN%2F%E6%A0%B8%E5%BF%83%22%5D%20--%3E%20SL%5B%22%E5%88%87%E7%89%87%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20SL%20--%3E%20EMBB%5B%22eMBB%20%E5%AE%B9%E9%87%8F%22%5D%0A%20%20SL%20--%3E%20URL%5B%22URLLC%20%E6%97%B6%E5%BB%B6%22%5D%0A%20%20URL%20--%3E%20SHORT%5B%22%E7%9F%AD%E6%97%B6%E9%9A%99%E4%B8%8E%E9%87%8D%E5%A4%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量 \\(C\\) 被切片划分：给 URLLC 的资源不能同时给 eMBB 满载。这是显式资源预留，与互联网核心的统计复用对照。移动性仍走核心锚，切片要跟着会话走。主干端到端：再可靠的空口也不替代应用校验。</p><p>与 Wi‑Fi 6 调度：都是时频资源分配；5G 有许可频谱与更硬的同步。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入网络开放 API 的全部 NEF。卫星与高延迟链路是下一课。后课默认：切片 = 隔离逻辑网；URLLC = 用效率换尾延迟。</p><p>实验室演示不等于全国覆盖的 URLLC SLA。</p><p>上一课留下的缺口在本课收口；「5G 切片与 URLLC」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/satellite-latency">卫星与高延迟链路</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切片隔离 SLA，强于单跳 DSCP。</li><li>URLLC 短时隙、重复、远离容量极限。</li><li>资源预留与互联网统计复用对照。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：3GPP TS 23.501、22.261。</li></ul>',10))])}const R=l(L,[["render",h]]);export{u as __pageData,R as default};
